import { useCallback, useState } from "react";

const useWalletExposure = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [data, setData] = useState<IRoot | null>(null);
  const [error, setError] = useState<string | null>(null);

  const checkWalletExposure = useCallback(async (walletAddress: string) => {
    if (!walletAddress) {
      setError("Wallet address is required");
      return;
    }

    setIsLoading(true);
    setError(null);
    try {
      const response = await fetch(
        "https://rkfl-point-of-sale-api-pub-464454934499.us-central1.run.app/aml/check-wallet-exposure",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            subject: {
              asset: "holistic",
              blockchain: "holistic",
              type: "address",
              hash: walletAddress,
            },
            customer_reference: "my_customer",
          }),
        }
      );

      if (!response.ok) {
        throw new Error("Failed to check wallet exposure");
      }

      const responseData = await response.json();
      setData(responseData); // Update state with response data
    } catch (err: any) {
      setError(err.message || "Error occurred while checking wallet exposure");
    } finally {
      setIsLoading(false);
    }
  }, []);

  const reset = useCallback(() => {
    setIsLoading(false);
    setData(null);
    setError(null);
  }, []);

  return {
    isLoading,
    data,
    error,
    checkWalletExposure,
    reset,
  };
};

export default useWalletExposure;

