import React, { ButtonHTMLAttributes } from "react";
import { EmailOutline } from "@emotion-icons/evaicons-outline/EmailOutline";
import AppLoader from "../Loader/AppLoader";
import { SEmailButton, SEmailButtonInner } from "./EmailButton.styles";
import { AppText } from "../Typography/Typography";

export interface IButton {
  text: string;
  isLoading?: boolean;
  icon: boolean;
  isDisabled?: boolean;
}

interface IButtonExtended extends IButton, Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> { }

const EmailButton: React.FC<IButtonExtended> = ({
  onClick,
  text,
  isLoading = false,
  isDisabled = false,
  icon = true,
  ...rest
}) => {
  const isActive = !isLoading && !isDisabled;

  return (
    <SEmailButton
      tabIndex={0}
      style={{
        ...rest.style,
      }}
      whileTap={{
        scale: 0.98,
      }}
      onClick={onClick}
      disabled={!isActive}
    >
      {isLoading ? (
        <AppLoader size="small" />
      ) : (
        <SEmailButtonInner>
          {icon && <EmailOutline size={16} color="#555" style={{ paddingRight: "1rem" }} />}
          <AppText cursor="inherit" as="p" type="labelSmall" color="inherit">
            {text}
          </AppText>
        </SEmailButtonInner>
      )}
    </SEmailButton>
  );
};

export default EmailButton;