import React, { useState } from "react";
import Button from "../Button/Button";
import useChangeEmail from "../../hooks/services/useChangeEmail";

import { SEmailInput, SError, SInfoText } from "./EmailModal.styles";
import { AppText } from "../Typography/Typography";

interface IEmailModal {
  onClose: (close: boolean) => void;
  onEmailChanged: (email: string) => void;
  existingEmail?: string | null;
  orderId: string;
  isEmailOpen: boolean;
}

const EmailModal: React.FC<IEmailModal> = ({ existingEmail, onClose, orderId, onEmailChanged: onEmailChanged }) => {
  const [email, setEmail] = useState(existingEmail ?? "");
  const [hasError, setHasError] = useState(false);

  const { changeEmail } = useChangeEmail();

  const onConfirmEmailChange = async () => {
    if (validateEmail(email)) {
      try {
        onEmailChanged(email);
        changeEmail({ orderId, payload: { email } });
        onClose(false);
      } catch (error) {
        console.error("Error changing email:", error);
      }
    } else {
      setHasError(true);
    }
  };

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  return (
    <div
      style={{
        width: "100%",
        background: "white",
        borderRadius: "8px",
      }}
    >
      <SEmailInput
        placeholder={"Email address"}
        value={email}
        hasError={hasError}
        onChange={({ target }) => {
          if (hasError) setHasError(false);
          setEmail(target.value);
        }}
      />
      {hasError && (
        <SError type="labelExtraSmall" as="p" color="error" align="left">
          {"Email must be valid"}
        </SError>
      )}
      <SInfoText style={{ marginTop: "16px" }}>
        <AppText type="labelExtraSmall" as="p" color="gray">
          {"Invoice will be sent as soon as payment is complete"}
        </AppText>
      </SInfoText>
      <div style={{ display: "flex", justifyContent: "space-between", marginTop: "16px", gap: "10px" }}>
        <Button style={{ width: "49%" }} variant="outline" onClick={() => onClose(false)}>
          Close
        </Button>
        <Button style={{ width: "49%" }} variant="filled" onClick={onConfirmEmailChange}>
          Update
        </Button>
      </div>
    </div>
  );
};

export default EmailModal;
