import { useCallback, useMemo, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import CryptoItem from "../CryptoItem/CryptoItem";
import useCurrenciesQuery from "../../hooks/services/useCurrenciesQuery";
import { TOrderResponse } from "../../hooks/services/useFetchOrderQuery";
import { SCryptoList } from "./CryptoList.styles";
import mixpanel from "mixpanel-browser";
import { AnalyticsEvents } from "../../analytics/AnalyticsEvent";
import { SContainer, SHomeLoader } from "../../pages/Home/Home.styles";
import { SearchBar } from "../SearchBar/SearchBar";
import { SWHeader, SWHeaderChild } from "../WalletScreening/WalletScreening.styles";
import { AppText } from "../Typography/Typography";
import AppLoader from "../Loader/AppLoader";
import useCheckout from "../../hooks/services/useCheckout";

interface ICryptoList {
  order: TOrderResponse | undefined;
  onCryptoSelect: (crypto: { symbol: string; kytNetwork: string }) => void;
  onOrderError: (currency: string) => void;
}

const CryptoList: React.FC<ICryptoList> = ({
  order,
  onCryptoSelect,
  onOrderError
}) => {
  const { checkout, isCheckoutLoading } = useCheckout();
  const orderId = order?.orderId || "";
  const { data: cryptos, isLoading: isCurrenciesLoading } = useCurrenciesQuery(orderId);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(false);

  const handleCryptoSelect = useCallback(
    async ({ symbol, kytNetwork }: {
      cryptoId: string;
      symbol: string;
      isLightningChecked: boolean;
      kytNetwork: string;
    }) => {
      try {
        setLoading(true);

        if (isCheckoutLoading) {
          return;
        }

        const orderReq = {
          locationId: order?.merchantLocationId,
          orderId: order?.orderId,
          amount: order?.paymentAmount.toString(),
          currency: order?.paymentCurrency.toString(),
          cryptoCurrency: symbol,
          cart: [
            {
              id: order?.orderId,
              name: `${order?.title} - ${order?.description}`,
              price: order?.paymentAmount.toString(),
              quantity: 1,
            },
          ],
          customerInfo: {
            name: order?.customerEmail,
            email: order?.customerEmail,
          },
        };

        try {
          const res = await checkout(orderReq);
          sessionStorage.setItem(orderId, JSON.stringify(res.data));
          setLoading(false);
          onCryptoSelect({ symbol, kytNetwork });
        } catch (_err) {
          setLoading(false);
          onOrderError(symbol);
        }
      } catch (error) {
        setLoading(false);
        onOrderError(symbol);
      }
    },
    [cryptos, order?.isEligibleForLightningNetwork]
  );

  const filteredCryptos = useMemo(() => {
    if (!search || !cryptos) return cryptos;
    const z = cryptos.filter((crypto) => crypto.title.toLowerCase().includes(search.toLowerCase()));
    return z;
  }, [search, cryptos]);

  return (
    <SContainer style={{ height: "100%" }}>
      <AnimatePresence>
        <motion.div
          initial={{
            scale: 0,
          }}
          animate={{
            scale: 1,
          }}
          transition={{ delay: 0.2 }}
        >
          <SWHeader>
            {filteredCryptos ? (
              <SWHeaderChild>
                <AppText type="labelSmall" as="h1" color="black">
                  Choose your preferred currency from&nbsp;
                </AppText>
                <AppText type="labelSmall" as="h1" color="purpleDark" bold>
                  {cryptos?.length || 0}
                </AppText>
                <AppText type="labelSmall" as="h1" color="black">
                  &nbsp;options
                </AppText>
              </SWHeaderChild>) :
              <SWHeaderChild>
                <AppText type="labelSmall" as="h1" color="black">
                  Fetching Currencies...
                </AppText>
              </SWHeaderChild>}
          </SWHeader>
        </motion.div>
        {filteredCryptos && !loading &&
          <div style={{ padding: "0 22px 22px 22px", height: "100%" }}>
            <SearchBar
              name="cryptoSearch"
              placeholder={"Search Currency"}
              onChange={(event) => {
                const { value } = event.target;
                setSearch(value);
              }}
            />
            <>
              {filteredCryptos ? (
                <div style={{
                  width: "100%",
                  height: "calc(100% - 140px)",
                  overflowY: "scroll",
                  scrollbarWidth: "none",
                  msOverflowStyle: "none",
                }}>
                  <SCryptoList
                    variants={{
                      show: {
                        transition: { staggerChildren: 0 }
                      },
                      hide: {
                        transition: { staggerChildren: 0 }
                      },
                    }}
                  >
                    {filteredCryptos.map(({ symbol, id, title, kytNetwork }, index) => (
                      <CryptoItem
                        key={`${id}-${index}`}
                        onSelect={(cryptoId: string, isLightningChecked: boolean) => {
                          mixpanel.track(AnalyticsEvents.CRYPTO_SELECTED, { Name: symbol });
                          handleCryptoSelect({ cryptoId, symbol, isLightningChecked, kytNetwork });
                        }}
                        id={id as string}
                        symbol={symbol}
                        title={title}
                        lightningEnabled={order?.isEligibleForLightningNetwork}
                        network={kytNetwork}
                      />
                    ))}
                  </SCryptoList>
                </div>
              ) : null}
            </>
          </div>
        }
        {(!filteredCryptos || loading) &&
          <SHomeLoader style={{ height: "53vh" }}>
            <AppLoader />
          </SHomeLoader>
        }
      </AnimatePresence>
    </SContainer>
  );
};

export default CryptoList;
