import { useEffect, useState } from "react";
import AppDropdown from "../DropDown/AppDropDown";
import EmailButton from "../EmailButton/EmailButton";
import { SWHeader } from "./PaymentDetails.styles";
import { AppText } from "../Typography/Typography";
import countries from "../../constants/countries";
import { SHomeLoader } from "../../pages/Home/Home.styles";
import AppLoader from "../Loader/AppLoader";

export interface PaymentDetails {
  amount: string;
  currency: string;
  country: string;
  firstName: string;
  lastName: string;
  email: string;
}

const PaymentDetailsComponent = ({ onPaymentDetails }: {
  onPaymentDetails: (details: PaymentDetails) => void;
}) => {

  const [amount, setAmount] = useState<string>("");
  const [currency, setCurrency] = useState<string>("");
  const [firstName, setFirstName] = useState<string>("");
  const [lastName, setLastName] = useState<string>("");
  const [email, setEmail] = useState<string>("");
  const [country, setCountry] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(false);

  const currencies = ["USD", "GBP", "EUR"];

  const handleAmountValid = (amount: any) => {
    const isAmountValid = amount !== "" || /^\d+(\.\d+)?$/.test(amount);
    return isAmountValid;
  };

  return (
    <div style={styles.container}>
      <SWHeader>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            width: "100%",
            height: "50px",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              textAlign: "left",
              minWidth: "auto",
              paddingLeft: "8px",
            }}
          >
            <AppText type="labelSmall" as="h1" color="black">
              Enter Payment Details
            </AppText>
          </div>
        </div>
      </SWHeader>
      <div style={styles.containerChild}>
        {!loading &&
          <>
            <div style={styles.row}>
              <input
                onChange={(e) => setAmount(e.target.value.replace(/\D/g, ""))}
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                placeholder="Enter Amount"
                style={styles.input}
              />
              <AppDropdown options={currencies} placeholder="Select Currency" onSelect={setCurrency} />
              <AppDropdown options={countries.map(c => c.name)} placeholder="Select Country" onSelect={(selectedCountry) => {
                const countryCode = countries.find(c => c.name === selectedCountry)?.code;
                setCountry(countryCode!!);
              }} />
            </div>

            <div style={styles.row}>
              <input onChange={(e) => setFirstName(e.target.value)} type="text" placeholder="Enter First Name" style={styles.input} />
              <input onChange={(e) => setLastName(e.target.value)} type="text" placeholder="Enter Last Name" style={styles.input} />
              <input onChange={(e) => setEmail(e.target.value)} type="text" placeholder="Enter Email" style={styles.input} />
            </div>

            <div style={styles.buttonRow}>
              <EmailButton onClick={() => {
                if (handleAmountValid(amount) && firstName !== "" && lastName !== "" && currency !== "" && country !== "" && email != "") {
                  setLoading(true);
                  onPaymentDetails({
                    amount: amount,
                    currency: currency,
                    firstName: firstName,
                    lastName: lastName,
                    country: country,
                    email: email
                  })
                }
              }} text="NEXT" icon={false} style={styles.button} />
            </div>
          </>
        }

        {loading &&
          <SHomeLoader>
            <AppLoader />
          </SHomeLoader>
        }
      </div>
    </div>
  );
};

const styles: { [key: string]: React.CSSProperties } = {
  container: {
    display: "flex",
    flexDirection: "column",
    gap: "16px",
    margin: "auto",
  },
  containerChild: {
    gap: "16px",
    paddingLeft: "16px",
    paddingRight: "16px",
    paddingBottom: "24px",
    display: "flex",
    flexDirection: "column",
    height: "200px"
  },
  row: {
    display: "flex",
    gap: "12px",
    height: "40px"
  },
  input: {
    flex: 1,
    lineHeight: "26px",
    borderRadius: "6px",
    border: "solid 1px #DDDDDD",
    padding: "8px",
    color: "#555",
    background: "white",
    width: "100%",
    outline: "none"
  },
  buttonRow: {
    display: "flex",
    justifyContent: "center",
    marginTop: "24px",
    marginBottom: "16px"
  },
  button: {
    width: "200px",
  },
};

export default PaymentDetailsComponent;


