import { default as ReactQRCode } from "react-qr-code";
import { SQrCode } from "./QRCode.styles";

interface IQRCode {
  value: string;
}

const AppQR: React.FC<IQRCode> = ({ value }) => {
  return (
    <SQrCode key="qrCodeComp">
      <ReactQRCode
        size={170}
        style={{ height: "auto", maxWidth: "100%", width: "100%" }}
        fgColor="#000000"
        bgColor="transparent"
        value={value}
        viewBox="0 0 170 170"
      />
    </SQrCode>
  );
};

export default AppQR;
