import React from "react";
import EditIcon from "../../assets/svg/edit.svg";
import { SOrderCard, SOrderCardContent, SOrderCardHeader, SOrderCardHeaderInner } from "./OrderCard.styles";
import { AppText } from "../Typography/Typography";

export interface IOrderCard {
  orderName: string;
  paymentAmount: number;
  paymentCurrency: string;
  merchantLogoBase64?: string | null;
  merchantName?: string;
  email: string | null;
  onEmailClick: () => void;
}

const OrderCard: React.FC<IOrderCard> = ({
  paymentAmount,
  paymentCurrency,
  merchantName,
  merchantLogoBase64,
  email,
  onEmailClick,
}) => {
  return (
    <SOrderCard>
      <SOrderCardHeader>
        <SOrderCardHeaderInner>
          <AppText
            as="p"
            type="labelSmall"
            color="black"
            align="left"
            bold
          >{`${paymentAmount} ${paymentCurrency}`}</AppText>
        </SOrderCardHeaderInner>
        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
          <AppText as="p" type="labelSmall" color="black" align="right">
            {merchantName ?? "-"}
          </AppText>
          {merchantLogoBase64 && <img src={`data:image/*;base64,${merchantLogoBase64}`} alt="store logo" height={45} />}
        </div>
      </SOrderCardHeader>
      <div onClick={onEmailClick}>
        <SOrderCardContent style={{ display: "flex", alignItems: "center", gap: "8px" }}>
          <AppText as="p" type="labelSmall" color="black" align="left">
            {email}
          </AppText>
          <img src={EditIcon} alt="icon" width="12" height="15" style={{ cursor: "pointer" }} />
        </SOrderCardContent>
      </div>
    </SOrderCard>
  );
};

export default OrderCard;
