import React, { useState } from "react";
import { Checkbox } from "../Checkbox/Checkbox";
import { keyUpToClick } from "../../helpers/keyUpToClick";
import { SCryptoItem, SCryptoDescription, SLightningWrapper } from "./CryptoItem.styles";
import { AppText } from "../Typography/Typography";


interface ICryptoItem {
  symbol?: string;
  id: string;
  onSelect: (id: string, isLightningChecked: boolean) => void;
  title: string;
  amount?: number;
  lightningEnabled?: boolean;
  network?: string;
}

const CryptoItem: React.FC<ICryptoItem> = ({
  symbol,
  id,
  onSelect,
  title,
  amount,
  lightningEnabled,
  network,
}) => {
  const [isLightningChecked, setIsLightningChecked] = useState(false);

  const iconPath = new URL(`../../assets/svg/crypto/${id.toLocaleLowerCase()}.svg`, import.meta.url).href;
  const placeholderPath = new URL(`../../assets/svg/crypto/placeholder.svg`, import.meta.url).href;

  return (
    <SCryptoItem>
      <SCryptoDescription
        tabIndex={0}
        onClick={() => {
          onSelect(id, isLightningChecked);
        }}
        onKeyUp={(e: React.KeyboardEvent) => {
          keyUpToClick({ e, cb: () => onSelect(id, isLightningChecked) });
        }}
      >
        <img
          src={iconPath}
          alt={title}
          width="40"
          onError={(event) => {
            const target = event.currentTarget;
            target.src = placeholderPath;
          }}
        />
        <div>
          <div style={{ marginBottom: "8px" }}>
            <AppText type="labelSmall" as="span" color="black" align="left" bold>
              {id}
            </AppText>
          </div>
          {network && (
            <AppText type="labelExtraSmall" as="span" color="subBlack" align="left" bold>
              Network : {network}
            </AppText>
          )}
          {amount && (
            <AppText type="labelSmall" as="span" color="black" align="left">
              {`${amount} ${symbol?.toUpperCase()}`}
            </AppText>
          )}
        </div>
      </SCryptoDescription>
      {lightningEnabled && (
        <SLightningWrapper
          tabIndex={0}
          onKeyUp={(e: React.KeyboardEvent) => {
            keyUpToClick({
              e,
              cb: () => {
                setIsLightningChecked((prev) => !prev);
              },
            });
          }}
        >
          <Checkbox
            name="withLighning"
            checked={isLightningChecked}
            onChange={() => setIsLightningChecked((prev) => !prev)}
          />
          <AppText type="labelSmall" as="span" color="black" align="left">
            {"Pay via Lightning Network"}
          </AppText>
        </SLightningWrapper>
      )}
    </SCryptoItem>
  );
};

export default CryptoItem;
