import { useState } from "react";
import { api } from "../../api";
import { GenericError } from "../../types/response/errors/generic-errors";

interface IChangeEmailPayload {
  email: string;
}

const useChangeEmail = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [isError, setIsError] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const changeEmail = async ({ orderId, payload }: { orderId: string; payload: IChangeEmailPayload }) => {
    setIsLoading(true);
    setIsError(false);
    setIsSuccess(false);

    try {
      const response = await api.put(`orders/${orderId}/email`, payload);
      setIsSuccess(true);
      return response;
    } catch (err: any) {
      setIsError(true);

      if (err?.response?.data?.errors?.orderId) {
        console.log("error.order-not-valid", { orderId });
        throw new GenericError(err.message);
      }

      throw new GenericError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  return { changeEmail, isLoading, isError, isSuccess };
};

export default useChangeEmail;
