import { UseQueryResult, useQuery } from "@tanstack/react-query";
import { api } from "../../api";
import { AxiosResponse } from "axios";
import { GenericError, IGenericError } from "../../types/response/errors/generic-errors";

interface ICurrency {
  chains: any;
  currentRate: string;
  decimals: number;
  fasterConfirmation: boolean;
  fiatEquivalent: any;
  fullTitle: string;
  title: string;
  id: string;
  isEnabled: boolean;
  isFiat: boolean;
  isMultipleNetwork: boolean;
  isPayment: boolean;
  isStableCoin: boolean;
  isTopCoin: boolean;
  kytNetwork: string;
  logo: string;
  network: string;
  networkMsg: string;
  provider: Array<string>;
  sort: any;
  symbol: string;
  upliftPercentage: string;
}
type TCurrenciesResponse = Array<ICurrency>;

const sortCurrenciesByOrder = (currencies: TCurrenciesResponse, topOrder: Array<string>) => {
  const orderMap: any = topOrder.reduce((acc, coin: any, index) => {
    return { ...acc, [coin]: index };
  }, {});

  return currencies.sort((a, b) => {
    const rankA = orderMap[a.id] !== undefined ? orderMap[a.id] : Infinity;
    const rankB = orderMap[b.id] !== undefined ? orderMap[b.id] : Infinity;
    return rankA - rankB;
  });
};

const useCurrenciesQuery = (orderId: string): UseQueryResult<TCurrenciesResponse, IGenericError> => {
  const fetchCurrencies = async (): Promise<TCurrenciesResponse> => {
    const res = await api
      .get<void, AxiosResponse<{ result: TCurrenciesResponse }>>("/External/pos/currencies")
      .catch((err) => {
        throw new GenericError(err.message);
      });
    const topOrder = ["BTC", "ETH", "USDT", "SOL", "XRP", "BNB", "DOGE", "USDC", "ADA", "TRX", "AVAX", "LINK"];
    const sortedCurrencies = sortCurrenciesByOrder(res.data.result, topOrder);

    return sortedCurrencies
      .filter(({ isFiat, isEnabled }) => isEnabled && !isFiat)
      .map((currency: any) => ({ ...currency, symbol: currency.id, title: currency.fullTitle }));
  };

  return useQuery<TCurrenciesResponse, IGenericError>({
    queryKey: ["currencies", orderId],
    queryFn: () => fetchCurrencies() as Promise<TCurrenciesResponse>,
    enabled: Boolean(orderId),
    retry: false,
  });
};

export default useCurrenciesQuery;
