import { useEffect } from "react";

import { SCountdown } from "./Timer.styles";
import { AppText } from "../../../../../components/Typography/Typography";
import secondsToHMS from "../../../../../helpers/time/secondsToHMS";
import useTimer from "../../../../../hooks/time/useTimer";

interface ITimer {
  expireAt: number | null;
  onFinish?: () => void;
}

const Timer: React.FC<ITimer> = ({ expireAt, onFinish }) => {
  const { timeLeft, finished } = useTimer(expireAt);
  useEffect(() => {
    if (finished && !!onFinish) {
      return onFinish();
    }
  }, [finished, onFinish]);

  const timeLeftHMS = secondsToHMS(timeLeft || 0);

  return (
    <div>
      <SCountdown>
        <AppText align="center" type="labelSmall" as="p" color="black" minWidth="115px">
          {"Time remaining: "}
          <AppText
            align="center"
            type="labelSmall"
            as="span"
            color="purpleDark"
            display="inline-block"
            fontWeight={700}
          >
            {`${timeLeftHMS.minutes}:${timeLeftHMS.seconds}`}
          </AppText>
        </AppText>
      </SCountdown>
    </div>
  );
};

export default Timer;
