import React, { useState, useEffect, useRef } from "react";

interface AppDropdownProps {
  options: string[];
  placeholder: string;
  onSelect: (selectedOption: string) => void;
}

const AppDropdown: React.FC<AppDropdownProps> = ({ options, placeholder, onSelect }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedOption, setSelectedOption] = useState(placeholder);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const handleSelect = (option: string) => {
    setSelectedOption(option);
    setIsOpen(false);
    onSelect(option);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  return (
    <div ref={dropdownRef} style={styles.dropdownContainer}>
      {/* Selected Option Box */}
      <div style={styles.dropdown} onClick={() => setIsOpen(!isOpen)}>
        <span>{selectedOption}</span>
        <span style={styles.arrow}>{isOpen ? "▴" : "▾"}</span>
      </div>

      {/* Dropdown Menu */}
      {isOpen && (
        <div style={styles.menu}>
          {options.map((option, index) => (
            <div key={index} style={styles.menuItem} onClick={() => handleSelect(option)}>
              {option}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

const styles: { [key: string]: React.CSSProperties } = {
  dropdownContainer: {
    position: "relative",
    width: "200px",
    height: "100%"
  },
  dropdown: {
    border: "1px solid #DDDDDD",
    paddingLeft: "10px",
    paddingRight: "10px",
    borderRadius: "4px",
    backgroundColor: "white",
    color: "#555",
    cursor: "pointer",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    fontSize: "13px",
    height: "100%"
  },
  arrow: {
    fontSize: "18px",
    marginLeft: "8px",
    display: "flex",
    alignItems: "center",
  },
  menu: {
    position: "absolute",
    top: "calc(100% + 6px)",
    left: 0,
    width: "100%",
    backgroundColor: "white",
    border: "1px solid #DDDDDD",
    borderRadius: "6px",
    boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
    zIndex: 10,
    maxHeight: "200px",
    overflowY: "auto",
    scrollbarWidth: "none",
    msOverflowStyle: "none",
  },
  menuItem: {
    padding: "10px",
    cursor: "pointer",
    color: "#555",
    textAlign: "center",
    borderBottom: "1px solid #DDDDDD",
  },
};

export default AppDropdown;
