import { useQuery, UseQueryResult } from "@tanstack/react-query";
import { api } from "../../api";
import { AxiosResponse } from "axios";
import { GenericError, IGenericError } from "../../types/response/errors/generic-errors";
import { queryKeys } from "../../constants/queryKeys";
import { ToastType } from "../../components/ToastProvider/ToastProvider";

export enum PaymentStatusEnum {
  PENDING = "PaymentPending",
  PAID = "Paid",
  DECLINED = "PaymentDeclined",
  AUTHORIZED = "Authorized",
}

export type TOrderResponse = {
  merchantLocationId: string | null;
  authorizedAtUtc: string | null;
  checkoutAtUtc: string | null;
  expireAtUtc: string | null;
  orderId: string;
  isEligibleForLightningNetwork: boolean;
  paymentAmount: number;
  paymentCurrency: string;
  cryptoPaymentCurrency: string | null;
  cryptoPaymentAmount: number | null;
  cryptoPaymentAddress: string | null;
  status: PaymentStatusEnum;
  cancelUrl: string;
  acceptUrl: string;
  description: string;
  customerEmail: string | null;
  merchantId: string;
  title: string | null;
  merchantOrderId: string | null;
  walletRiskScore: string | null;
  fromWalletAddress: string | null;
  walletRiskSkipped: boolean;
};
const useFetchOrderQuery = ({
  orderId,
  enabled = true,
  showToast,
}: {
  orderId: string;
  enabled?: boolean;
  showToast: (message: string, type: ToastType) => void;
}): UseQueryResult<TOrderResponse, IGenericError> => {
  const fetchOrder = async () => {
    const res = await api.get<void, AxiosResponse<TOrderResponse>>(`orders/${orderId}`).catch((err) => {
      if (err?.response?.data?.errors?.orderId) {
        showToast("Invalid Order", ToastType.ERROR)
        throw new GenericError(err.message);
      }
      showToast(err.message, ToastType.ERROR)
      throw new GenericError(err.message);
    });
    return res.data;
  };

  return useQuery<TOrderResponse, IGenericError>({
    queryKey: [queryKeys.order, orderId],
    queryFn: fetchOrder,
    enabled: enabled && !!orderId,
    retry: false,
  });
};

export default useFetchOrderQuery;
