import styled from "@emotion/styled";
import { motion } from "framer-motion";

import { IButton } from "./Button";

interface ISButton extends Omit<IButton, "children"> {
    border?: string;
}

export const SButton = styled(motion.button, { shouldForwardProp: (prop) => prop !== "minWidth" }) <ISButton>`
    border-radius: 7px;
    outline: none;
    border: ${(props) => (props.disabled || !props.border ? "none" : "solid 1px black")};
    display: flex;
    justify-content: center;
    align-items: center;
    cursor: pointer;
    padding: 1em 1.5em;
    &:disabled {
      cursor: not-allowed;
    }
    &:focus-visible {
      transition: all 0.2s ease;
      background: black !important;
    }
    z-index: 1;
    flex: 1;
  `;
