import React from "react";
import ReactDOM from "react-dom/client";
import CheckoutModal from "./CheckoutModal";

export const processCheckout = async (orderDetails, accessToken, merchantLocationId) => {
  try {
    // Combine the order details with the merchant location ID
    const paymentData = { ...orderDetails, merchantLocationId };

    // Create the modal container if it doesn't exist
    let modalRoot = document.getElementById("checkout-modal-root");
    if (!modalRoot) {
      modalRoot = document.createElement("div");
      modalRoot.id = "checkout-modal-root";
      document.body.appendChild(modalRoot);
    }

    // Create a root for the modal and render the CheckoutModal
    const root = ReactDOM.createRoot(modalRoot);
    const closeModal = () => {
      root.unmount();
      document.body.removeChild(modalRoot);
    };
    root.render(
      <CheckoutModal
        key={"checkoutModal"}
        paymentData={paymentData}
        aToken={accessToken}
        onClose={closeModal}
      />
    );

    return { success: true };
  } catch (error) {
    console.error("Checkout error:", error);
    return { success: false, error: error.message };
  }
};
