import { useMutation, UseMutationResult } from "@tanstack/react-query";
import { api } from "../../api";
import { GenericError } from "../../types/response/errors/generic-errors";

export interface IDeclineOrderResponse { }

const useDeclineOrder = (): UseMutationResult<
  IDeclineOrderResponse,
  GenericError,
  { orderId: string }
> => {
  const declineOrder = async ({ orderId }: { orderId: string }): Promise<IDeclineOrderResponse> => {
    try {
      const result = await api.post<IDeclineOrderResponse>(`Orders/${orderId}/cancel`);
      return result.data;
    } catch (err: any) {
      throw new GenericError(err.message);
    }
  };

  return useMutation<IDeclineOrderResponse, GenericError, { orderId: string }>({
    mutationFn: declineOrder,
    onSuccess: () => { },
  });
};

export default useDeclineOrder;
