import React from "react";
import { IsCanceledEnum } from "../../types/session-storage/session-storage";
import Button from "../Button/Button";
import { sessionStorageItems } from "../../constants/storage";
import useDeclineOrder from "../../hooks/services/useDeclineOrder";

interface ICancelOrderModal {
  onConfirm?: () => void;
  onCancel: () => void;
  orderId: string;
}

const CancelOrderModal: React.FC<ICancelOrderModal> = ({ orderId, onConfirm, onCancel }) => {
  const { mutate: declineOrder } = useDeclineOrder();

  const confirmCancelationCallback = () => {
    if (onConfirm) {
      onConfirm();
    }
    if (orderId) {
      declineOrder({ orderId });
    }
    sessionStorage.setItem(sessionStorageItems.isCanceled, IsCanceledEnum.TRUE);
  };

  return (
    <div style={{ background: "white", width: "100%", fontSize: "14px", color: "black" }}>
      <div style={{ fontWeight: "bold", lineHeight: "26px", fontSize: "17px", paddingBottom: "12px" }}>
        Are you sure you want to cancel this payment?
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", gap: "10px", marginTop: "10px" }}>
        <Button style={{ width: "100%" }} variant="secondary" onClick={onCancel}>
          {"No, continue"}
        </Button>
        <Button style={{ width: "100%" }} variant="danger" onClick={confirmCancelationCallback}>
          {"Yes, cancel"}
        </Button>
      </div>
    </div>
  );
};

export default CancelOrderModal;
