import { useEffect, useState } from "react";
import AppQR from "react-qr-code";
import { ConnectButton } from "@rainbow-me/rainbowkit";
import { useAccount } from "wagmi";
import { useDisconnect } from "wagmi";
import CheckMarkIcon from "../../assets/svg/checkmark.svg";
import CrossMarkIcon from "../../assets/svg/cross.svg";
import LeftArrowIcon from "../../assets/svg/left-arrow.svg";
import Button from "../Button/Button";
import EmailButton from "../EmailButton/EmailButton";
import { AppText } from "../Typography/Typography";
import useFetchOrderQuery from "../../hooks/services/useFetchOrderQuery";
import useWalletExposure from "../../hooks/services/useWalletCheck";
import { SWHeader, SWNotes } from "./WalletScreening.styles";
import mixpanel from "mixpanel-browser";
import { AnalyticsEvents } from "../../analytics/AnalyticsEvent";
import { SQRCode } from "../Payment/PaymentPending/PaymentPending.styles";
import AppLoader from "../../components/Loader/AppLoader";
import LoaderGif from "../../assets/svg/loading.gif";
import "@rainbow-me/rainbowkit/styles.css";
import BottomSheet from "../BottomSheet/BottomSheet";
import { useToast } from "../ToastProvider/ToastProvider";

const WalletScreeningComponent = ({
  orderId,
  cryptoCurrency,
  network,
  onVerificationResult,
  onBack,
}: {
  orderId: string;
  cryptoCurrency: string;
  network: string;
  onVerificationResult: (success: boolean) => void;
  onBack: () => void;
}) => {
  const [isWalletSkipOpen, setIsWalletSkipOpen] = useState(false);

  const { disconnect } = useDisconnect();
  const { isConnected, address } = useAccount();
  const [mobileVerification, setIsMobileVerification] = useState(false);
  const [walletAddress, setWalletAddress] = useState<string | null>("");
  const { isLoading, data: walletData, error: walletDataError, checkWalletExposure, reset } = useWalletExposure();
  const { showToast } = useToast();

  useEffect(() => {
    if (address) {
      checkWalletExposure(address);
    }
  }, [address, checkWalletExposure]);

  const handleProceedToPayment = () => {
    onVerificationResult(true);
  };

  const textAnimation = {
    initial: {
      scale: 0,
    },
    animate: {
      scale: 1,
    },
    transition: { delay: 0.2 },
  };

  const {
    refetch: refetchInternalOrder,
  } = useFetchOrderQuery({ orderId, enabled: true, showToast });

  useEffect(() => {
    const refetchInterval = setInterval(async () => {
      const { data } = await refetchInternalOrder();

      if (mobileVerification && data?.walletRiskScore && parseFloat(data.walletRiskScore) <= 6) {
        handleProceedToPayment();
      }
    }, 3000);

    return () => clearInterval(refetchInterval);
  }, [orderId, mobileVerification, refetchInternalOrder]);

  const handleManualWalletTest = () => {
    if (!walletAddress) return;
    checkWalletExposure(walletAddress);
  };

  const skipVerification = () => {
    mixpanel.track(AnalyticsEvents.WALLET_VERIFY_SKIPPED);
    handleProceedToPayment();
  };

  const handleDisconnect = () => {
    if (isConnected) {
      console.log(`Disconnecting wallet: ${address}`);
      disconnect();
      reset();
    } else {
      console.error("No wallet is connected!");
    }
  };

  const navigateMobileScreening = (isMobile: boolean) => {
    setIsMobileVerification(isMobile);
  };

  return (
    <>
      <div style={{ width: "100%" }}>
        <div style={{ width: "100%" }}>
          {isLoading && (
            <div
              style={{
                width: "100%",
                height: "500px",
                minWidth: "300px",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              <AppLoader />
            </div>
          )}

          {!isLoading && !walletData && (
            <div style={{ width: "100%" }}>
              <SWHeader>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    width: "100%",
                    height: "50px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      textAlign: "left",
                      minWidth: "auto",
                      paddingLeft: "8px",
                    }}
                  >
                    {!mobileVerification && (
                      <img
                        src={LeftArrowIcon}
                        onClick={onBack}
                        alt="icon"
                        width="12"
                        height="15"
                        style={{ cursor: "pointer", marginRight: "8px" }}
                      />
                    )}
                    <AppText type="labelSmall" as="h1" color="black">
                      {mobileVerification ? "Mobile " : ""} Wallet Verification
                    </AppText>
                  </div>

                  {!mobileVerification && !isLoading && !walletData && (
                    <div>
                      <Button
                        key="skipScreen"
                        style={{ height: "20px" }}
                        variant="outline"
                        onClick={() => setIsWalletSkipOpen(true)}
                      >
                        SKIP
                      </Button>
                    </div>
                  )}
                </div>
              </SWHeader>

              <div style={{ padding: "16px" }}>
                {walletDataError && !mobileVerification && (
                  <div style={{ paddingBottom: "20px" }}>
                    <p style={{ color: "red", lineHeight: "16px" }}>
                      There was an issue with this wallet. Please try a different one.
                    </p>
                  </div>
                )}

                <div style={{ display: "flex", gap: "10px", flexDirection: "column" }}>
                  {!mobileVerification && (
                    <div>
                      <div style={{ paddingBottom: "16px", lineHeight: "22px", color: "black" }}>
                        Click "Connect Wallet" or manually enter your wallet details below to allow us to screen your
                        wallet. This pre-transaction check helps minimize delays and payment issues. For a seamless
                        transaction, use a successfully screened wallet without modifications.
                      </div>

                      {!isConnected && (
                        <ConnectButton.Custom>
                          {({
                            account,
                            chain,
                            openAccountModal,
                            openChainModal,
                            openConnectModal,
                            authenticationStatus,
                            mounted,
                          }) => {
                            const ready = mounted && authenticationStatus !== "loading";
                            const connected =
                              ready &&
                              account &&
                              chain &&
                              (!authenticationStatus || authenticationStatus === "authenticated");

                            return (
                              <div
                                {...(!ready && {
                                  "aria-hidden": true,
                                  style: {
                                    opacity: 0,
                                    pointerEvents: "none",
                                    userSelect: "none",
                                  },
                                })}
                              >
                                {(() => {
                                  if (!connected) {
                                    return (
                                      <EmailButton
                                        onClick={() => {
                                          mixpanel.track(AnalyticsEvents.CONNECT_WALLET_VERIFICATION);
                                          openConnectModal();
                                        }}
                                        text="Connect Wallet"
                                        icon={false}
                                      />
                                    );
                                  }

                                  if (chain.unsupported) {
                                    return (
                                      <button onClick={openChainModal} type="button">
                                        Wrong network
                                      </button>
                                    );
                                  }

                                  return (
                                    <div style={{ display: "flex", gap: 12 }}>
                                      <button
                                        onClick={openChainModal}
                                        style={{ display: "flex", alignItems: "center" }}
                                        type="button"
                                      >
                                        {chain.hasIcon && (
                                          <div
                                            style={{
                                              background: chain.iconBackground,
                                              width: 12,
                                              height: 12,
                                              borderRadius: 999,
                                              overflow: "hidden",
                                              marginRight: 4,
                                            }}
                                          >
                                            {chain.iconUrl && (
                                              <img
                                                alt={chain.name ?? "Chain icon"}
                                                src={chain.iconUrl}
                                                style={{ width: 12, height: 12 }}
                                              />
                                            )}
                                          </div>
                                        )}
                                        {chain.name}
                                      </button>

                                      <button onClick={openAccountModal} type="button">
                                        {account.displayName}
                                        {account.displayBalance ? ` (${account.displayBalance})` : ""}
                                      </button>
                                    </div>
                                  );
                                })()}
                              </div>
                            );
                          }}
                        </ConnectButton.Custom>
                      )}
                      <div style={{ paddingBottom: "8px", lineHeight: "22px", paddingTop: "12px", color: "black" }}>
                        Want to verify from mobile?{" "}
                        <span
                          style={{ color: "#007bff", cursor: "pointer", textDecoration: "none" }}
                          onClick={() => {
                            mixpanel.track(AnalyticsEvents.MOBILE_VERIFICATION);
                            navigateMobileScreening(true);
                          }}
                        >
                          Click here
                        </span>
                      </div>
                      <div style={{ display: "flex", alignItems: "center", paddingBottom: "20px", paddingTop: "16px" }}>
                        <div style={{ flex: 1, height: "1px", backgroundColor: "#ccc" }}></div>
                        <div style={{ padding: "0 10px", whiteSpace: "nowrap", color: "black" }}>OR</div>
                        <div style={{ flex: 1, height: "1px", backgroundColor: "#ccc" }}></div>
                      </div>
                      <div>
                        <div style={{ fontWeight: "bold", paddingBottom: "16px", color: "black" }}>Manual Verification</div>
                        <div style={{ display: "flex", flexDirection: "row", gap: "10px", paddingBottom: "20px" }}>
                          <input
                            value={walletAddress as string}
                            onChange={(e) => setWalletAddress(e.target.value)}
                            type="text"
                            placeholder="Enter Your Wallet Address"
                            style={{
                              width: "100%",
                              lineHeight: "26px",
                              borderRadius: "6px",
                              border: "solid 1px black",
                              padding: "8px",
                              color: "black",
                              background: "white"
                            }}
                          />
                          <EmailButton
                            onClick={() => {
                              mixpanel.track(AnalyticsEvents.MANUAL_VERIFICATION);
                              handleManualWalletTest();
                            }}
                            text="Verify"
                            icon={false}
                          />
                        </div>
                      </div>
                    </div>
                  )}
                  {mobileVerification && (
                    <div>
                      <div style={{ paddingBottom: "16px", lineHeight: "22px", textAlign: "center", color: "black" }}>
                        Please scan the QR code below to verify your wallet on your mobile device.
                      </div>
                      <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
                        <div style={{ paddingBottom: "8px", lineHeight: "22px", paddingTop: "12px" }}>
                          <SQRCode
                            key="paymentQR"
                            initial={{
                              scale: 0,
                            }}
                            animate={{
                              scale: 1,
                            }}
                            transition={{ type: "spring", velocity: 4, delay: 0.4 }}
                          >
                            <AppQR
                              value={`https://checkout.staging.xbd.app/payment?orderId=${orderId}&&cryptoCurrency=${cryptoCurrency}&&network=${network}&&platform=web&&verify=true`}
                            />
                          </SQRCode>
                        </div>

                        <li style={{ display: "flex", margin: "16px 0" }}>
                          <img src={LoaderGif} width="20" style={{ marginRight: "8px" }} />
                          <AppText type="labelSmall" as="p" color="black">
                            Awaiting Verification Status
                          </AppText>
                        </li>

                        <div style={{ display: "flex", flexDirection: "row", gap: "10px", paddingTop: "10px" }}>
                          <EmailButton onClick={() => navigateMobileScreening(false)} text="BACK" icon={false} />
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {!isLoading && walletData && evaluateWalletRisk(walletData.risk_score) && (
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: "10px",
                padding: "2em",
                justifyContent: "center",
                verticalAlign: "center",
              }}
            >
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: "10px",
                  textAlign: "center",
                  justifyContent: "center",
                  verticalAlign: "center", color: "black"
                }}
              >
                <div style={{ display: "flex", justifyContent: "center", height: "80px", paddingBottom: "20px" }}>
                  <img src={CheckMarkIcon} alt="Checkmark Icon" />
                </div>
                <div style={{ padding: "0 10px" }}>
                  <span style={{ fontWeight: "bold" }}>Verified Wallet :</span> {address || walletAddress || ""}
                </div>
                <div style={{ fontSize: "22px" }}>You're ready to Pay!</div>
              </div>

              <SWNotes key="screenSuccess" {...textAnimation}>
                <ul style={{ paddingLeft: "20px", margin: 0, color: "gray" }}>
                  <li>
                    Your wallet has been successfully verified. To avoid any payment delays, please use this wallet
                    without any modifications.
                  </li>
                  <li>
                    Do not modify your wallet. Changes like adding funds or switching wallets may trigger a review,
                    causing a delay in payment processing.
                  </li>
                </ul>
              </SWNotes>

              {isConnected && !evaluateWalletRisk(walletData.risk_score) && (
                <div
                  style={{ textDecoration: "underline", cursor: "pointer", padding: "0px 0px 20px 0px" }}
                  onClick={() => disconnect()}
                >
                  Disconnect and try a different wallet.
                </div>
              )}
              <div style={{ width: "100%", display: "flex", justifyContent: "center" }}>
                <EmailButton onClick={handleProceedToPayment} text="PAY" icon={false} style={{ width: "200px" }} />
              </div>
            </div>
          )}

          {!isLoading && walletData && !evaluateWalletRisk(walletData.risk_score) && (
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: "10px",
                textAlign: "center",
                justifyContent: "center",
                verticalAlign: "center",
                color: "black"
              }}
            >
              <div style={{ display: "flex", justifyContent: "center", height: "80px", paddingBottom: "20px" }}>
                <img src={CrossMarkIcon} alt="Checkmark Icon" />
              </div>
              <span> Wallet: {formatWalletAddress(address || walletAddress || "")}</span>
              <div style={{ fontSize: "22px" }}>Screening Failed!</div>
              <div style={{ fontSize: "16px", lineHeight: "18px" }}>This wallet cannot be used for transactions.</div>
              <Button style={{ width: "100%" }} variant="filled" onClick={() => handleDisconnect()}>
                Disconnect and try a different wallet
              </Button>
            </div>
          )}
        </div>
      </div>

      <BottomSheet isOpen={isWalletSkipOpen} onClose={() => setIsWalletSkipOpen(false)}>
        <div style={{ background: "white", width: "100%", fontSize: "14px", color: "black" }}>
          <div style={{ fontWeight: "bold", lineHeight: "26px", fontSize: "17px", paddingBottom: "12px" }}>
            Skip Wallet Verification
          </div>
          <div style={{ paddingBottom: "15px", lineHeight: "19px" }}>
            If you skip wallet verification, we won't be able to assess your wallet in advance or determine if your
            payment is likely to be accepted.
          </div>
          <div style={{ paddingBottom: "15px", lineHeight: "19px" }}>
            If your payment requires manual review, your funds may be
            <strong style={{ fontWeight: "bold" }}> temporarily held</strong> and will only be released once the
            review is complete.
          </div>

          <div style={{ paddingBottom: "15px", lineHeight: "19px" }}>
            NOTE: Goods or services will only be provided after the review is complete.
          </div>

          <div style={{ display: "flex", justifyContent: "space-between", gap: "10px", marginTop: "10px" }}>
            <EmailButton onClick={() => setIsWalletSkipOpen(false)} text="Cancel" icon={false} />
            <EmailButton onClick={skipVerification} text="Agree & Proceed" icon={false} />
          </div>
        </div>
      </BottomSheet>
    </>
  );
};

export default WalletScreeningComponent;

// Helper Functions
function formatWalletAddress(walletAddress: string): string {
  if (walletAddress.length === 0) return "";
  if (typeof walletAddress !== "string" || walletAddress.length < 6) {
    throw new Error("Invalid wallet address");
  }
  const firstThree = walletAddress.slice(0, 3);
  const lastThree = walletAddress.slice(-3);
  return `${firstThree}...${lastThree}`;
}

function evaluateWalletRisk(exposure: number): boolean {
  if (!exposure) return true;

  if (typeof exposure !== "number" || exposure < 0 || exposure > 10) {
    throw new Error("Exposure must be a number between 0 and 10");
  }
  return exposure <= 5; // "✔" : "✘";
}

