import { useCallback, useEffect, useState } from "react";
import Timer from "./components/Timer/Timer";
import {
  SNotes,
  SPaymentPendingButtons,
  SPaymentPendingRootWrapper,
  SPaymentPendingText,
  SPaymentPendingWrapper,
  SQRCode,
} from "./PaymentPending.styles";
import { AnimatePresence } from "framer-motion";
import mixpanel from "mixpanel-browser";
import { AnalyticsEvents } from "../../../analytics/AnalyticsEvent";
import CancelOrderModal from "../../../components/CancelOrderModal/CancelOrderModal";
import DisclaimerModal from "../../../components/DisclaimerModal/DisclaimerModal";
import { OrderResult } from "../../../types/services/crypto";
import { AppText } from "../../../components/Typography/Typography";
import Button from "../../../components/Button/Button";
import useFetchOrderQuery, { PaymentStatusEnum } from "../../../hooks/services/useFetchOrderQuery";
import LoaderGif from "../../../assets/svg/loading.gif";
import BottomSheet from "../../BottomSheet/BottomSheet";
import { DateTime } from "luxon";
import AppQR from "../../QRCode/QRCode";
import sendDetails from "../../../hooks/services/useSendDetails";
import { ToastType, useToast } from "../../ToastProvider/ToastProvider";

const PaymentPending = ({
  orderId,
  network,
  onPaymentResult,
}: {
  orderId: string,
  network: string;
  onPaymentResult: (result: OrderResult) => void;
}) => {
  const [isDisclaimerOpen, setIsDisclaimerOpen] = useState(false);
  const [showCancelOrderModal, setShowCancelOrderModal] = useState(false);
  const [isOrderEnabled, setIsOrderEnabled] = useState(true);
  const orderSession = JSON.parse(sessionStorage.getItem(orderId) as string);
  const [qrString, setQrString] = useState("");
  const [cryptoAddress, setCryptoAddress] = useState("");
  const [cryptoAmount, setCryptoAmount] = useState("");
  const [cryptoCurrency, setCryptoCurrency] = useState("");
  const { showToast } = useToast();

  const {
    data: order,
    refetch: refetchOrder,
  } = useFetchOrderQuery({ orderId, enabled: isOrderEnabled, showToast });

  const authorizedAtUtc = order?.authorizedAtUtc || "";
  const expireTimestamp = DateTime.fromISO(authorizedAtUtc, { zone: "utc" })
    .plus({ minutes: 20 })
    .valueOf();

  const redirectByStatus = useCallback(
    (orderStatus: PaymentStatusEnum) => {
      if (orderStatus === PaymentStatusEnum.PAID) {
        logPaymentStatus(true);
        onPaymentResult(OrderResult.SUCCESS);
        return;
      }
      if (orderStatus === PaymentStatusEnum.DECLINED) {
        logPaymentStatus(false);
        onPaymentResult(OrderResult.FAILED);
        return;
      }
    },
    [order?.status, orderId]
  );

  useEffect(() => {
    if (orderSession) {
      setQrString(orderSession.result.meta.qrString);
      setCryptoAddress(orderSession.result.meta.receiverAddress);
      setCryptoAmount(orderSession.result.totalAmount);
      setCryptoCurrency(orderSession.result.cryptoCurrency);
    }
  }, [orderSession]);

  useEffect(() => {
    const refetchInterval = setInterval(() => {
      refetchOrder();
    }, 3000);
    if (order?.status === PaymentStatusEnum.PAID) {
      clearInterval(refetchInterval);
      logPaymentStatus(true);
      onPaymentResult(OrderResult.SUCCESS);
      return;
    }
    if (order?.status === PaymentStatusEnum.DECLINED) {
      clearInterval(refetchInterval);
      logPaymentStatus(false);
      onPaymentResult(OrderResult.FAILED);
      return;
    }
    return () => {
      setIsOrderEnabled(false);
      clearInterval(refetchInterval);
    };
  }, [order?.status, orderId, refetchOrder]);

  const handleTimeout = useCallback(() => {
    if (order) {
      setIsOrderEnabled(false);
      redirectByStatus(order?.status);
    }
  }, [order, redirectByStatus]);

  const textAnimation = {
    initial: {
      scale: 0,
    },
    animate: {
      scale: 1,
    },
    transition: { delay: 0.2 },
  };

  const copyToClipboard = (val: string) => {
    if (navigator) {
      navigator.clipboard.writeText(val);
      showToast("Address Copied", ToastType.SUCCESS)
    }
  };

  const handleSendDetailsToEmail = () => {
    if (order && order.customerEmail) {
      mixpanel.track(AnalyticsEvents.SEND_PAYMENT_DETAILS);
      sendDetails({ orderId, cryptoAddress, cryptoAmount, cryptoCurrency }, showToast);
    }
  };

  const logPaymentStatus = (success: boolean) => {
    mixpanel.track(success ? AnalyticsEvents.PAYMENT_SUCCESS : AnalyticsEvents.PAYMENT_FAILURE);
  };

  const handleOrderCancel = () => {
    mixpanel.track(AnalyticsEvents.ORDER_CANCEL);
    setShowCancelOrderModal(false);
    onPaymentResult(OrderResult.CANCELLED);
  };

  return (
    <>
      {order && orderSession ? (
        <div style={{ width: "100%" }}>
          <SPaymentPendingRootWrapper>
            <SPaymentPendingWrapper>
              <AnimatePresence>
                <SPaymentPendingText key="titlePayment" {...textAnimation}>
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      width: "100%",
                      height: "50px",
                    }}
                  >
                    <div style={{ textAlign: "left", minWidth: "auto", paddingLeft: "12px" }}>
                      <AppText type="labelSmall" as="h1" color="black">
                        {"Scan the QR code to complete your payment"}
                      </AppText>
                    </div>

                    <div style={{ textAlign: "right", paddingRight: "12px" }}>
                      <Timer onFinish={handleTimeout} expireAt={expireTimestamp} />
                    </div>
                  </div>
                </SPaymentPendingText>
                <div style={{ padding: "22px" }}>
                  <div
                    style={{ display: "flex", alignItems: "center", gap: "16px", width: "100%", paddingBottom: "16px" }}
                  >
                    <div style={{ flex: 1, textAlign: "left" }}>
                      <AppText as="p" type="labelSmall" color="black" align="left" bold>
                        Payable
                      </AppText>
                      <div style={{ display: "flex", alignItems: "center", gap: "8px", marginTop: "10px" }}>
                        <AppText as="p" type="input" color={cryptoAmount ? "purpleMain" : "black"} bold align="left">
                          {cryptoAmount && cryptoCurrency ? `${cryptoAmount} ${cryptoCurrency}` : "-"}
                        </AppText>
                      </div>
                      <div style={{ display: "flex", alignItems: "center", gap: "4px", marginTop: "10px" }}>
                        <AppText as="p" type="labelSmall" color="black" align="left">
                          Network :
                        </AppText>
                        <AppText as="p" type="labelSmall" color="purpleDark" align="left" bold>
                          {network}
                        </AppText>
                      </div>
                    </div>

                    <div style={{ flex: 1, display: "flex", justifyContent: "center" }}>
                      <SQRCode
                        key="paymentPageQR"
                        initial={{ scale: 0 }}
                        animate={{ scale: 1 }}
                        transition={{ type: "spring", velocity: 4, delay: 0.4 }}
                      >
                        <AppQR value={qrString || ""} />
                      </SQRCode>
                    </div>
                    <li style={{ display: "flex", margin: "16px 0", flex: 1 }}>
                      <img src={LoaderGif} width="20" style={{ marginRight: "8px" }} />
                      <AppText type="labelSmall" as="p" color="black">
                        Awaiting Payment
                      </AppText>
                    </li>
                  </div>

                  <SPaymentPendingButtons key="pedingButtons">
                    <Button
                      key="copyAddress"
                      variant="outline"
                      onClick={() => {
                        copyToClipboard(cryptoAddress || "");
                      }}
                    >
                      {"Copy Address"}
                    </Button>

                    <Button key="emailQR" variant="outline" onClick={handleSendDetailsToEmail}>
                      {"Email QR"}
                    </Button>

                    <Button key="cancelOrder" variant="cancel" onClick={() => setShowCancelOrderModal(true)}>
                      {"Cancel"}
                    </Button>
                  </SPaymentPendingButtons>

                  <SNotes key="disclaimer" {...textAnimation}>
                    <ul style={{ paddingLeft: "20px", margin: 0, color: "gray" }}>
                      <li>{"If you're sending from an exchange, include extra network fees to ensure your transaction is processed. Missing fees may result in a failed transaction."}</li>
                      <li>
                        <span style={{ fontWeight: "bold" }}>Important:</span> If you proceed with payment using a
                        wallet that has not been screened or if the screened wallet has been altered, your payment may
                        be frozen for further review.
                      </li>
                      <li>
                        {"Payments are processed by Xbase Digital UAB on behalf of the merchant who referred you to this invoice. "}
                        <span style={{ color: "#0000EE", cursor: "pointer" }} onClick={() => setIsDisclaimerOpen(true)}>
                          {"Terms and conditions apply."}
                        </span>
                      </li>
                    </ul>
                  </SNotes>
                </div>
              </AnimatePresence>
            </SPaymentPendingWrapper>
          </SPaymentPendingRootWrapper>
        </div>
      ) : <></>}
      <BottomSheet isOpen={isDisclaimerOpen} onClose={() => setIsDisclaimerOpen(false)}>
        <div style={{ background: "white", width: "100%", fontSize: "14px", color: "black" }}>
          <DisclaimerModal onCancel={() => setIsDisclaimerOpen(false)} />
        </div>
      </BottomSheet>
      <BottomSheet isOpen={showCancelOrderModal} onClose={() => setShowCancelOrderModal(false)}>
        <div style={{ background: "white", width: "100%", fontSize: "14px", color: "black" }}>
          <CancelOrderModal orderId={orderId} onCancel={() => setShowCancelOrderModal(false)} onConfirm={handleOrderCancel} />
        </div>
      </BottomSheet>
    </>
  );
};

export default PaymentPending;
