import { api } from "../../api";
import { ToastType } from "../../components/ToastProvider/ToastProvider";
import { GenericError } from "../../types/response/errors/generic-errors";

type SendDetailsParams = {
  orderId: string;
  cryptoAddress: string;
  cryptoAmount: string;
  cryptoCurrency: string;
};

const sendDetails = async ({ orderId, cryptoAddress, cryptoAmount, cryptoCurrency }: SendDetailsParams,
  showToast: (message: string, type: ToastType) => void
) => {
  try {
    showToast("Payment details have been sent to your email.", ToastType.SUCCESS)
    await api.post(`orders/${orderId}/pos/sendDetails`, {
      cryptoAddress,
      cryptoAmount,
      cryptoCurrency,
    });
  } catch (error) {
    const errorMessage = error instanceof GenericError ? error.errorMessage : "Something went wrong!";
    showToast(errorMessage, ToastType.ERROR)
  }
};

export default sendDetails;
