import { useEffect, useState } from "react";
import CryptoList from "../../components/CryptoList/CryptoList";
import WalletScreeningComponent from "../../components/WalletScreening/WalletScreening";
import { SContainer, SOrderHeader, SWalletParent } from "./Home.styles";
import { Steps } from "antd";
import { OrderResult } from "../../types/services/crypto";
import EmailModal from "../../components/EmailModal/EmailModal";
import PaymentCanceled from "../../components/Payment/PaymentCanceled/PaymentCanceled";
import PaymentFailure from "../../components/Payment/PaymentFailure/PaymentFailure";
import PaymentPending from "../../components/Payment/PaymentPending/PaymentPending";
import PaymentSuccess from "../../components/Payment/PaymentSuccess/PaymentSuccess";
import OrderCard from "../../components/OrderCard/OrderCard";
import LogoIcon from "../../assets/svg/logo/logo.svg";
import CloseIcon from "../../assets/svg/close.png";
import useFetchOrderQuery from "../../hooks/services/useFetchOrderQuery";
import { useMerchantSettingsQuery } from "../../hooks/services/useMerchantSettingsQuery";
import BottomSheet from "../../components/BottomSheet/BottomSheet";
import { ToastType, useToast } from "../../components/ToastProvider/ToastProvider";
import mixpanel from "mixpanel-browser";
import { AnalyticsEvents } from "../../analytics/AnalyticsEvent";
import { createOrder } from "../../hooks/services/createOrder";
import PaymentDetailsComponent, { PaymentDetails } from "../../components/PaymentDetails/PaymentDetails";

export interface ICryptoSelection {
  symbol: string;
  kytNetwork: string;
}

interface HomeProps {
  paymentData: any;
  token: string;
  onClose: () => void;
}

export const Home: React.FC<HomeProps> = ({ paymentData, token, onClose }) => {
  const PAYMENT_DETAILS = "Enter Details";
  const CHOOSE_CRYPTO = "Choose Crypto";
  const WALLET_SCREENING = "Verify Wallet";
  const PAY = "Pay";
  const STATUS = "Status";

  const [currentStep, setCurrentStep] = useState(0);
  const [currentStepName, setCurrentStepName] = useState<string | null>(null);
  const { showToast } = useToast();
  const [orderId, setOrderId] = useState<string | null>(null);
  const [steps, setSteps] = useState<string[]>([]);
  const [cryptoSymbol, setCryptoSymbol] = useState<string>("");
  const [cyrptoNetwork, setCyrptoNetwork] = useState<string>("");
  const [orderResult, setOrderResult] = useState<OrderResult>(OrderResult.NONE);
  const [isEmailModalOpen, setIsEmailModalOpen] = useState<boolean>(false);
  const [email, setEmail] = useState<string | undefined>(undefined);

  const { data: order } = useFetchOrderQuery({ orderId: orderId ?? "", enabled: orderId !== null, showToast });
  const { data: merchantSettings } = useMerchantSettingsQuery({ merchantId: order?.merchantId, enabled: !!order?.merchantId, showToast });

  useEffect(() => {
    initAnalytics();

    let enableAmountForm = paymentData.amount === undefined;
    let enableScreening = !!paymentData.screening;

    if (enableAmountForm !== undefined && !enableAmountForm) {
      handleOrder();
    }

    let stepsList = [
      enableAmountForm ? PAYMENT_DETAILS : null,
      CHOOSE_CRYPTO,
      enableScreening ? WALLET_SCREENING : null,
      PAY,
      STATUS,
    ].filter(Boolean) as string[];

    setCurrentStepName(stepsList[0]);
    setSteps(stepsList);
  }, [paymentData]);

  useEffect(() => {
    if (order?.customerEmail) {
      setEmail(order.customerEmail);
    }
  }, [order]);

  const handleOrder = async () => {
    const result = await createOrder(token, paymentData);
    if (result) {
      setOrderId(result.orderId);
    }
  };

  const handleCryptoSelect = ({ symbol, kytNetwork }: ICryptoSelection) => {
    if (symbol) {
      setCryptoSymbol(symbol);
      setCyrptoNetwork(kytNetwork);
      nextStep();
    }
  };

  const handleOrderError = (currency: string) => {
    showToast(
      `Sorry, we couldn't process ${currency.toUpperCase()} at the moment. Please try a different currency.`,
      ToastType.ERROR
    );
  };

  const nextStep = () => {
    if (currentStep < steps.length - 1) {
      let nextStepper = currentStep + 1;
      setCurrentStep(nextStepper);
      setCurrentStepName(steps[nextStepper])
    }
  };

  const handleVerificationResult = (success: boolean) => {
    if (success) {
      nextStep();
    }
  };

  const handlePaymentDetails = async (details: PaymentDetails) => {
    if (details) {
      paymentData.amount = parseFloat(details.amount);
      paymentData.currency = details.currency;
      paymentData.shopperFirstName = details.firstName;
      paymentData.shopperLastName = details.lastName;
      paymentData.shopperResidenceCountry = details.country;
      paymentData.email = details.email;

      const result = await createOrder(token, paymentData);
      if (result) {
        setOrderId(result.orderId);
        nextStep();
      }
    }
  };

  const back = () => {
    setCurrentStep(0);
    setCurrentStepName(steps[0]);
  };

  const handlePaymentResult = (result: OrderResult) => {
    setOrderResult(result);
    nextStep();
  };

  const handleEmailUpdated = (email: string) => {
    setEmail(email);
  };

  const renderPaymentStatus = () => {
    switch (orderResult as OrderResult) {
      case OrderResult.SUCCESS:
        return <PaymentSuccess />;
      case OrderResult.FAILED:
        return <PaymentFailure />;
      default:
        return <PaymentCanceled />;
    }
  };

  const initAnalytics = () => {
    const analyticsToken = "b60457668fca2a810c0d2e32fd1cb33a";
    mixpanel.init(analyticsToken);
    mixpanel.track(AnalyticsEvents.WEB_APP_LAUNCH, { orderId: orderId });
  };

  return (
    <>
      <div style={{ height: "85vh", paddingLeft: "16px", paddingRight: "16px" }}>
        <SOrderHeader centered={currentStepName === PAYMENT_DETAILS}>
          <img
            src={LogoIcon}
            width="150" height="40"
          />
          {currentStepName !== PAYMENT_DETAILS && merchantSettings && order && (
            <OrderCard
              email={email!!}
              paymentAmount={order.paymentAmount}
              paymentCurrency={order.paymentCurrency}
              orderName={order.description}
              merchantName={merchantSettings.displayName}
              merchantLogoBase64={merchantSettings?.logoImage}
              onEmailClick={() => setIsEmailModalOpen(true)}
            />)}
          {merchantSettings && order &&
            <img
              src={CloseIcon}
              width="20" height="20" style={{ alignSelf: "flex-start", cursor: "pointer" }} onClick={onClose} />
          }
        </SOrderHeader>

        <div style={{ marginBottom: "24px", marginTop: "24px" }}>
          <Steps
            progressDot
            current={currentStep}
            items={steps.map((step, index) => ({
              title: <span style={{ fontWeight: index === currentStep ? "bold" : "normal" }}>{step}</span>,
            }))} />
        </div>

        {currentStepName === PAYMENT_DETAILS &&
          <div style={{ maxHeight: "81%" }}>
            <SContainer>
              <SWalletParent>
                <PaymentDetailsComponent onPaymentDetails={handlePaymentDetails} />
              </SWalletParent>
            </SContainer>
          </div>
        }

        {currentStepName === CHOOSE_CRYPTO &&
          <div style={{ height: "81%" }}>
            <SContainer style={{ height: "100%" }}>
              <CryptoList
                order={order}
                onCryptoSelect={handleCryptoSelect}
                onOrderError={handleOrderError} />
            </SContainer>
          </div>}

        {currentStepName === WALLET_SCREENING &&
          <div style={{ maxHeight: "81%" }}>
            <SContainer>
              <SWalletParent>
                <WalletScreeningComponent
                  orderId={orderId!!}
                  cryptoCurrency={cryptoSymbol!}
                  network={cyrptoNetwork!}
                  onVerificationResult={handleVerificationResult}
                  onBack={back}
                />
              </SWalletParent>
            </SContainer>
          </div>
        }

        {currentStepName === PAY && <div style={{ maxHeight: "81%" }}>
          <SContainer>
            <PaymentPending orderId={orderId!!} network={cyrptoNetwork} onPaymentResult={handlePaymentResult} />
          </SContainer>
        </div>}

        {currentStepName === STATUS && <div style={{ maxHeight: "81%" }}>
          <SContainer style={{ height: "100%" }}>{renderPaymentStatus()}</SContainer>
        </div>}
      </div>
      {orderId && order &&
        <BottomSheet isOpen={isEmailModalOpen} onClose={() => setIsEmailModalOpen(false)}>
          <EmailModal
            onClose={() => setIsEmailModalOpen(false)}
            isEmailOpen={isEmailModalOpen}
            existingEmail={order?.customerEmail}
            orderId={orderId}
            onEmailChanged={(email) => { handleEmailUpdated(email); }}
          />
        </BottomSheet>
      }
    </>
  );
}

export default Home;