import { authenticate } from './auth';
import { processCheckout } from './api';

let sdkInstance = null;

function initGlobalSdk({ grant_type, client_id, client_secret, merchantLocationId }) {
  if (sdkInstance) return sdkInstance;

  sdkInstance = {
    grant_type,
    client_id,
    client_secret,
    merchantLocationId,
    token: null,

    async authenticate() {
      if (!this.token) {
        this.token = await authenticate({
          grant_type: this.grant_type,
          client_id: this.client_id,
          client_secret: this.client_secret,
        });
      }
      return this.token;
    },

    async checkout(orderDetails) {
      const token = await this.authenticate();
      return processCheckout(orderDetails, token, this.merchantLocationId);
    },
  };

  console.log('SDK Initialized with:', sdkInstance);
  return sdkInstance;
}

export { initGlobalSdk, authenticate, processCheckout };

if (typeof window !== 'undefined') {
  window.MyCheckoutSDK = { init: initGlobalSdk };
}

export default {
  initGlobalSdk,
  authenticate,
  processCheckout,
};