import React, { ButtonHTMLAttributes, useMemo } from "react";
import { themeColors } from "../../theme/theme.colors";
import { SButton } from "./Button.styles";
import AppLoader from "../Loader/AppLoader";
import { AppText } from "../Typography/Typography";


export interface IButton {
  children: string | React.ReactNode;
  minWidth?: string;
  variant?: "filled" | "outline" | "transparent" | "secondary" | "danger" | "cancel";
  isLoading?: boolean;
  isDisabled?: boolean;
}

interface IButtonExtended extends IButton, Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children" | "color"> { }

const Button: React.FC<IButtonExtended> = ({
  onClick,
  children,
  minWidth,
  variant = "filled",
  isLoading = false,
  isDisabled = false,
  ...rest
}) => {
  const isActive = !isLoading && !isDisabled;

  const initialBackground = useMemo(() => {
    if (!isActive) {
      return themeColors.blackOpaque;
    }
    if (variant === "outline" || variant === "cancel") {
      return themeColors.white;
    }
    if (variant === "transparent") {
      return themeColors.transparent;
    }
    if (variant === "secondary") {
      return themeColors.whiteLight;
    }
    if (variant === "danger") {
      return themeColors.error;
    }
    return themeColors.purpleDark;
  }, [isActive, variant]);

  const initialColor = useMemo(() => {
    if (!isActive) {
      return themeColors.whiteOpaque;
    }
    if (variant === "outline") {
      return themeColors.purpleDark;
    }

    if (variant === "cancel") {
      return themeColors.error;
    }

    if (variant === "transparent") {
      return themeColors.black;
    }
    if (variant === "secondary") {
      return themeColors.black;
    }
    return themeColors.white;
  }, [isActive, variant]);

  const activeStyle = useMemo(() => {
    if (!isActive) {
      return themeColors.blackOpaque;
    }
    if (variant === "transparent") {
      return themeColors.transparent;
    }
    if (variant === "filled") {
      return `${themeColors.purpleDark}90`;
    }
    return `${themeColors.purpleDark}60`;
  }, [isActive, variant]);

  return (
    <SButton
      tabIndex={0}
      style={{
        ...rest.style,
      }}
      initial={{
        background: initialBackground,
        color: initialColor,
      }}
      whileHover={{
        background: activeStyle,
      }}
      whileTap={{
        scale: 0.98,
      }}
      onClick={onClick}
      color={initialColor}
      disabled={!isActive}
      minWidth={minWidth}
      border={variant === "outline" ? themeColors.purpleDark : variant === "cancel" ? themeColors.error : undefined}
    >
      {isLoading ? (
        <AppLoader size="small" />
      ) : (
        <AppText cursor="inherit" type="labelSmall" as="p" color="inherit">
          {children}
        </AppText>
      )}
    </SButton>
  );
};

export default Button;
