import { useMutation } from "@tanstack/react-query";
import { api } from "../../api";
import { GenericError } from "../../types/response/errors/generic-errors";

const useCheckout = () => {
  const mutation = useMutation({
    mutationFn: async (data: any) => {
      try {
        const response = await api.post("/External/pos/purchase/generate/qr", data);
        return response;
      } catch (err: any) {
        if (err?.response?.data?.errors?.orderId) {
          throw new GenericError(err.message);
        }
        throw new GenericError(err.message);
      }
    },
  });

  return {
    checkout: mutation.mutateAsync,
    isCheckoutLoading: mutation.isPending,
    isCheckoutError: mutation.isError,
    isCheckoutSuccess: mutation.isSuccess,
  };
};

export default useCheckout;
