import { api } from "../../api";

export const createOrder = async (accessToken: string, paymentData: any) => {
  try {
    const response = await api.put("api/orders/authorize", paymentData, {
      headers: {
        Authorization: `Bearer ${accessToken}`,
      },
    });

    return response.data;
  } catch (error) {
    console.error(
      "Error processing checkout:",
      error instanceof Error ? error.message : "Unknown error"
    );
    return null;
  }
};
