import { InputHTMLAttributes } from "react";
import { FieldValues, Path, UseFormRegister } from "react-hook-form";
import { Search } from "@emotion-icons/boxicons-regular/Search";

import { SSearchBar, SSearchBarInput } from "./SearchBar.styles";

export type TFormInputProps<TFormValues extends FieldValues> = InputHTMLAttributes<HTMLInputElement> & {
  name: Path<TFormValues>;
  rules?: any;
  register?: UseFormRegister<TFormValues>;
};

export const SearchBar = <TFormValues extends Record<string, unknown>>({
  className,
  name,
  register,
  rules,
  ...props
}: TFormInputProps<TFormValues>) => {
  return (
    <SSearchBar className={className} aria-live="polite">
      <Search size={14} />
      <SSearchBarInput name={name} {...props} {...(register && register(name, rules))} />
    </SSearchBar>
  );
};
